  package   org . cts . registry ;   import  java . util .  * ;  import    org . apache . log4j . Logger ;   public final class RegistryManager  {   static final Logger  LOGGER =  Logger . getLogger  (  RegistryManager . class ) ;   private final  Map  < String , Registry >  registries =  new  HashMap  < String , Registry >  ( ) ;   private final  List  < RegistryManagerListener >  listeners =  new  ArrayList  < RegistryManagerListener >  ( ) ;   public RegistryManager  ( )  { }   public void addRegistryManagerListener  (  RegistryManagerListener listener )  {   listeners . add  ( listener ) ; }   public boolean removeRegistryManagerListener  (  RegistryManagerListener listener )  {  return  listeners . remove  ( listener ) ; }   private void fireRegistryAdded  (  String functionName )  {  for ( RegistryManagerListener listener : listeners )  {   listener . registryAdded  ( functionName ) ; } }   public boolean contains  (  String name )  {  return  registries . containsKey  ( name ) ; }   public  String  [ ] getRegistryNames  ( )  {   LOGGER . trace  ( "Getting all function names" ) ;   Set  < String >  k =  registries . keySet  ( ) ;  return  k . toArray  (  new String  [  k . size  ( ) ] ) ; }   public Registry getRegistry  (  String registryName )  {   LOGGER . trace  (  "Getting the registry " + registryName ) ;  Registry  registry =  registries . get  (  registryName . toLowerCase  ( ) ) ;  if  (  registry == null )  {  return null ; } else  {  return registry ; } }   public void addRegistry  (  Registry registryClass )  {   addRegistry  ( registryClass , false ) ; }   public void addRegistry  (  Registry registry ,  boolean replace )  {   LOGGER . trace  (  "Adding a new registry " +  registry . getRegistryName  ( ) ) ;  String  registryName =   registry . getRegistryName  ( ) . toLowerCase  ( ) ;  if  (   ! replace &&  registries . containsKey  ( registryName ) )  {  throw  new IllegalArgumentException  (   "Registry " + registryName + " already exists" ) ; }   registries . put  ( registryName , registry ) ;   fireRegistryAdded  ( registryName ) ; } }